import {
  Box,
  Card,
  CardContent,
  Container,
  Grid,
  Typography,
} from "@mui/material";
import React from "react";
import cardTopImg from "../../../assets/images/cardTopImg.png";
import profileImg from "../../../assets/images/cardProfileImg.png";
import "../../../styles/animation.css";
import { useRef } from "react";
import { useEffect } from "react";
import { useState } from "react";

const customerExperience = [1, 2, 3, 4, 5, 6];
const CustomerExperience = () => {
  //animation
  const [visibleIndices, setVisibleIndices] = useState([]);
  const cardsRef = useRef([]);
  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            const index = cardsRef.current.indexOf(entry.target);
            if (index !== -1 && !visibleIndices.includes(index)) {
              setVisibleIndices((prev) => [...prev, index]);
            }
          }
        });
      },
      { threshold: 0.1 }
    );

    cardsRef.current.forEach((card) => {
      if (card) {
        observer.observe(card);
      }
    });

    return () => {
      cardsRef.current.forEach((card) => {
        if (card) {
          observer.unobserve(card);
        }
      });
    };
  }, [visibleIndices]);
  return (
    <>
      <Box>
        <Container
          maxWidth={"lg"}
          sx={{
            px: { xs: 5, sm: 10, lg: 15, xl: 20 },
            pt: { xs: 2, sm: 0 },
          }}
        >
          <Grid container rowGap={{ xs: 10, md: 10, lg: 35 }}>
            <Grid
              item
              xs={12}
              sx={{
                display: "flex",
                flexDirection: "column",
                gap: { xs: 1, sm: 3 },
                alignItems: "center",
              }}
            >
              <Typography
                sx={{
                  fontSize: {
                    xs: "26px",
                    sm: "44px",
                    md: "54px",
                    lg: "64px",
                  },
                  fontWeight: 500,
                  lineHeight: {
                    xs: "34px",
                    sm: "63px",
                    md: "73px",
                    lg: "83px",
                  },
                  color: "#201D28",
                  textAlign: "center",
                }}
                className="fade-in-up-whoweare"
              >
                Customer Experience
              </Typography>
              <Typography
                sx={{
                  fontSize: { xs: "14px", sm: "18px" },
                  fontWeight: 500,
                  lineHeight: { xs: "26px", sm: "28px" },
                  color: "#69668E",
                  textAlign: "center",
                }}
                className="fade-in-up-whoweare"
              >
                Look at what our customers say about us.
              </Typography>
            </Grid>
            <Grid item container spacing={5} xs={12}>
              {customerExperience.map((item, index) => (
                <Grid
                  item
                  xs={12}
                  md={4}
                  key={index}
                  ref={(el) => (cardsRef.current[index] = el)}
                  sx={{
                    opacity: visibleIndices.includes(index) ? 1 : 0,
                    transform: visibleIndices.includes(index)
                      ? "translateX(0)"
                      : "translateX(-50px)",
                    transition: "opacity 1s ease, transform 1s ease",
                    transitionDelay: visibleIndices.includes(index)
                      ? `${index * 0.3}s` // Staggered effect by index
                      : "0s",
                  }}
                >
                  <Card
                    sx={{
                      // width: "100%",
                      boxShadow: "none",
                      bgcolor: "#F5F5F9",
                      borderRadius: "24px",
                    }}
                  >
                    <CardContent>
                      <img src={cardTopImg} />
                      <Typography
                        sx={{
                          fontSize: { md: "18px", lg: "20px" },
                          fontWeight: 500,
                          color: "#000000",
                          lineHeight: { lg: "31px" },
                          my: 5,
                        }}
                      >
                        Digital Waves has been instrumental in transforming our
                        online presence. Highly recommended for anyone looking
                        to elevate their digital strategy."
                      </Typography>

                      <Box
                        sx={{ display: "flex", alignItems: "center", gap: 3 }}
                      >
                        <img src={profileImg} alt="profile image" />
                        <Box>
                          <Typography
                            sx={{
                              fontSize: { xs: "14px", lg: "16px" },
                              lineHeight: { lg: "24px" },
                              color: "#151515",
                              fontWeight: 500,
                            }}
                          >
                            Ahmed H.
                          </Typography>
                          <Typography
                            sx={{
                              fontSize: "12px",
                              fontWeight: 500,
                              color: "#5E5E5E",
                              lineHeight: "18px",
                            }}
                          >
                            JEDDAH, SAUDI ARABIA
                          </Typography>
                        </Box>
                      </Box>
                    </CardContent>
                  </Card>
                </Grid>
              ))}
            </Grid>
          </Grid>
        </Container>
      </Box>
    </>
  );
};

export default CustomerExperience;
